mapper.select:
select sa.ID,staff.BADGE,staff.NAME,staff.COMP_NAME,staff.DEP_NAME,staff.PHONE,sa.APPEAL_TYPE,
sa.STATUS,sa.APPEAL_DESC,sa.APPEAL_IMGS,sa.CREATE_TIME,sa.REPLY_NAME,sa.REPLY_DESC,sa.REPLY_TIME,
sa.ischange
from SMT_STAFF_APPEAL sa
left join SMT_STAFF staff on sa.STAFF_BADGE=staff.BADGE


		AND sa.ID=#{query.id}



		AND sa.STAFF_BADGE=#{query.staffBadge}



		AND sa.APPEAL_TYPE=#{query.appealType}



		AND sa.CREATE_TIME between #{query.beginTime} and #{query.endTime}



		AND sa.STATUS=#{query.status}



		and sa.PARK_ID in

			#{item}




ORDER BY sa.CREATE_TIME desc
